import { it, expect } from 'vitest'
import { waitForDelay } from '@orkestrel/test'
import { userEvent } from 'vitest/browser'
import { makeElement, writeReading } from './helpers.js'

it('censuses native browser features', async () => {
	const declarations = ['anchor-name: --a','position-anchor: --a','position-area: bottom','position-try-fallbacks: flip-block','position-visibility: anchors-visible','interpolate-size: allow-keywords','height: calc-size(auto, size)','transition-behavior: allow-discrete','overlay: auto','scrollbar-gutter: stable']
	const selectors = [':popover-open',':modal','::backdrop','::details-content',':open',':state(x)']
	const popover = makeElement('div')
	popover.popover = 'hint'
	const button = makeElement('button')
	let source: unknown
	try { Reflect.apply(popover.showPopover, popover, [{source:button}]); source = {accepted:true,open:popover.matches(':popover-open')}; popover.hidePopover() } catch(error) { source = String(error) }
	const details = makeElement('details')
	details.innerHTML='<summary>Details</summary>Content'
	const events: unknown[]=[]
	details.addEventListener('toggle',event=>events.push({target:'DETAILS',event:'toggle',cancelable:event.cancelable}))
	for (const element of [details,popover]) element.addEventListener('beforetoggle', event => events.push({target:element.tagName,cancelable:event.cancelable}))
	details.open = true
	popover.showPopover()
	await waitForDelay(50)
	popover.hidePopover();await waitForDelay(30)
	const summary=details.querySelector('summary');if(summary)await userEvent.click(summary)
	await waitForDelay(50)
	const api = {popover:'popover' in HTMLElement.prototype, showPopover:'showPopover' in HTMLElement.prototype,togglePopover:'togglePopover' in HTMLElement.prototype,source,hint:popover.popover,inert:'inert' in HTMLElement.prototype,requestClose:'requestClose' in HTMLDialogElement.prototype,closedBy:'closedBy' in HTMLDialogElement.prototype,CloseWatcher:'CloseWatcher' in window,command:'command' in HTMLButtonElement.prototype,commandForElement:'commandForElement' in HTMLButtonElement.prototype,interestForElement:'interestForElement' in HTMLButtonElement.prototype,detailsName:'name' in HTMLDetailsElement.prototype,getAnimations:'getAnimations' in Element.prototype,startViewTransition:'startViewTransition' in document,beforetoggle:events}
	const dialog = makeElement('dialog'); dialog.setAttribute('closedby','any')
	const control = {property:CSS.supports('imaginary-feasibility: yes'),selector:CSS.supports('selector(:imaginary-feasibility)')}
	expect(control.property).toBe(false); expect(control.selector).toBe(false)
	expect(CSS.supports(declarations[0] ?? '')).toBe(true)
	await writeReading('feature-census',1,{declarations,selectors},{css:Object.fromEntries(declarations.map(value=>[value,CSS.supports(value)])),selectors:Object.fromEntries(selectors.map(value=>[value,CSS.supports('selector('+value+')')])),api,closedby:Reflect.get(dialog,'closedBy')},{expected:'Made-up property and selector are false; supported real declarations are true.',reading:control},'Read parser support separately from the measured behavior in later probes.')
	popover.remove();details.remove();button.remove();dialog.remove()
})

