import { it, expect } from 'vitest'
import { userEvent } from 'vitest/browser'
import { waitForDelay } from '@orkestrel/test'
import { makeElement, makeStyle, readBox, readStyles, readStack, readTabs, settleFrame, writeReading } from './helpers.js'

it('measures modal UA differences and neutralization', async () => {
	const trigger=makeElement('button');trigger.id='opener';trigger.textContent='Open'
	const control=makeElement('div','modal fade show','display:block')
	control.innerHTML='<div class="modal-dialog"><div class="modal-content"><button>First</button><button>Last</button></div></div>'
	const backdrop=makeElement('div','modal-backdrop fade show')
	const controlChild=control.querySelector('.modal-dialog')
	if(!controlChild) throw new Error('Missing control dialog')
	const baseline={style:readStyles(control),box:readBox(control),child:readBox(controlChild)}
	control.remove();backdrop.remove()
	const high=makeElement('div','','position:fixed;inset:0;z-index:2147483647;background:red');high.id='high-sibling'
	const dialog=makeElement('dialog','modal fade')
	dialog.innerHTML='<div class="modal-dialog"><div class="modal-content"><button id="first">First</button><button id="last">Last</button></div></div>'
	const child=dialog.querySelector('.modal-dialog');const last=dialog.querySelector('#last')
	if(!child || !(last instanceof HTMLElement))throw new Error('Missing native dialog')
	const events: unknown[]=[]
	dialog.addEventListener('cancel',event=>events.push({event:'cancel',cancelable:event.cancelable}))
	dialog.addEventListener('close',()=>events.push({event:'close'}))
	trigger.focus();dialog.showModal();dialog.classList.add('show');await waitForDelay(360)
	const raw={style:readStyles(dialog),box:readBox(dialog),focus:document.activeElement?.id}
	dialog.close();makeStyle('dialog.modal[open] { display: block; }');trigger.focus();dialog.showModal();await settleFrame()
	const initial={style:readStyles(dialog),box:readBox(dialog),child:readBox(child),backdrop:readStyles(dialog,'::backdrop'),stack:readStack(innerWidth-10,innerHeight-10),focus:document.activeElement?.id,tabs:await readTabs(last)}
	const declarations='dialog.modal { margin: 0; border: 0; padding: 0; max-width: none; max-height: none; color: inherit; background: transparent; }'
	makeStyle(declarations);await settleFrame()
	const neutralized={style:readStyles(dialog),box:readBox(dialog),child:readBox(child)}
	const differences=Object.keys(baseline.style).filter(key=>baseline.style[key]!==neutralized.style[key])
	trigger.focus();const outsideFocus={attempt:'opener',actual:document.activeElement?.id}
	await userEvent.keyboard('{Escape}');await waitForDelay(80)
	const closed={open:dialog.open,events,focus:document.activeElement?.id}
	expect(initial.style['border-width']).not.toBe(baseline.style['border-width'])
	expect(neutralized.box).toEqual(baseline.box)
	expect(differences).toEqual([])
	await writeReading('dialog-modal',2,{viewport:{width:innerWidth,height:innerHeight},declarations:declarations+' dialog.modal[open] { display: block; }'}, {raw,initial,neutralized,differences,outsideFocus,closed},{expected:'The ordinary div has no dialog UA border or margin; normalization restores its box.',reading:baseline},'A native modal requires UA box normalization and display:block when open; Escape and focus behavior are measured independently.')
	dialog.remove();high.remove();trigger.remove()
})

it('measures top layer insertion versus z-index', async () => {
	const low=makeElement('div','','position:fixed;left:100px;top:100px;width:160px;height:160px;z-index:1;background:red');low.id='low'
	const dialog=makeElement('dialog','modal show','display:block;margin:0;border:0;padding:0;max-width:none;max-height:none')
