import { it, expect } from 'vitest'
import { cdp } from 'vitest/browser'
import { waitForDelay } from '@orkestrel/test'
import { makeElement, makeStyle, readBox, readStyles, readTransition, settleFrame, writeReading } from './helpers.js'

it('measures fade reflow and starting-style',async()=>{
	const baseline=makeElement('div','modal fade')
	const reflow=await readTransition(baseline,()=>{baseline.style.display='block';void baseline.offsetHeight;baseline.classList.add('show')},230)
	baseline.remove()
	const declarations='.discrete.modal { transition-behavior: allow-discrete; } .discrete.modal.show { display:block; } @starting-style { .discrete.modal.show { opacity:0; } }'
	makeStyle(declarations)
	const discrete=makeElement('div','modal fade discrete');await settleFrame()
	const starting=await readTransition(discrete,()=>discrete.classList.add('show'),230);discrete.remove()
	const plain=makeElement('div','modal fade','transition:none')
	const control=await readTransition(plain,()=>{plain.style.display='block';void plain.offsetHeight;plain.classList.add('show')},180);plain.remove()
	let reduced:unknown
	try {
		await cdp().send('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]})
		const element=makeElement('div','modal fade discrete');await settleFrame()
		reduced={matches:matchMedia('(prefers-reduced-motion: reduce)').matches,reading:await readTransition(element,()=>element.classList.add('show'),180)};element.remove()
		await cdp().send('Emulation.setEmulatedMedia',{features:[]})
	}catch(error){reduced={error:String(error)}}
	expect(control.animations.length).toBe(0);expect(reflow.animations.length).toBeGreaterThan(0);expect(starting.animations.length).toBeGreaterThan(0)
	await writeReading('fade-discrete',5,{declarations,duration:150},{reflow,starting,reduced},{expected:'transition:none yields no animation or transitionend, unlike both enabled fade paths.',reading:control},'Starting-style provides an entering fade without the Bootstrap forced-reflow idiom; reduced motion is independently measured.')
})

it('measures intrinsic height and exclusive details',async()=>{
	const measured=makeElement('div','collapse','width:200px');measured.innerHTML='<div style="height:120px">Content</div>'
	measured.className='collapsing';measured.style.height='0px';void measured.offsetHeight
	const target=measured.scrollHeight
	const baseline=await readTransition(measured,()=>measured.style.height=target+'px',420)
	measured.className='collapse show';measured.style.height='';const cleared=readBox(measured);measured.remove()
	const intrinsic=makeElement('div','collapsing','width:200px;height:0;interpolate-size:allow-keywords;transition:height .35s ease');intrinsic.innerHTML='<div style="height:120px">Content</div>';await settleFrame()
	const auto=await readTransition(intrinsic,()=>intrinsic.style.height='auto',420);intrinsic.remove()
	const numeric=makeElement('div','collapsing','width:200px;height:0;transition:height .35s ease');numeric.innerHTML='<div style="height:120px">Content</div>';await settleFrame()
	const control=await readTransition(numeric,()=>numeric.style.height='auto',420);numeric.remove()
	const declarations='details.probe { interpolate-size:allow-keywords; } details.probe::details-content { transition:height .35s; height:0; overflow:hidden; } details.probe[open]::details-content { height:auto; }'
	makeStyle(declarations)
	const first=makeElement('details','probe');first.name='exclusive';first.innerHTML='<summary>First</summary><div style="height:120px">Content</div>'
	const second=makeElement('details','probe');second.name='exclusive';second.innerHTML='<summary>Second</summary><div style="height:120px">Content</div>'
	const events:unknown[]=[];first.addEventListener('transitionend',event=>events.push({property:event.propertyName,elapsed:event.elapsedTime,pseudo:event.pseudoElement}))
	await settleFrame();const detailStart=performance.now();first.open=true;await settleFrame();const animations=first.getAnimations({subtree:true}).map(animation=>({playState:animation.playState,timing:animation.effect?.getComputedTiming()}));await waitForDelay(420)
	const details={animations,events,arrival:performance.now()-detailStart,box:readBox(first),pseudo:readStyles(first,'::details-content')}
	second.open=true;await settleFrame();const exclusive={first:first.open,second:second.open}
	expect(control.animations.length).toBe(0);expect(auto.animations.length).toBeGreaterThan(0);expect(exclusive).toEqual({first:false,second:true})
	await writeReading('collapse-intrinsic',6,{duration:350,target,declarations},{baseline,cleared,auto,details,exclusive},{expected:'Without interpolate-size, height:0 to auto snaps without an animation.',reading:control},'Intrinsic height interpolation animates the ordinary collapse; details content animation and exclusive opening are recorded separately.')
	first.remove();second.remove()
